package bits.ui;
import bits.dao.UserDAO; import bits.model.User; import javax.swing.*; import java.awt.*; import java.sql.SQLException;
public class LoginFrame extends JFrame {
 private final JTextField email=new JTextField(22); private final JPasswordField password=new JPasswordField(22);
 public LoginFrame(){super("BITS | Sign in");setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(980,620);setMinimumSize(new Dimension(820,520));setLocationRelativeTo(null);JPanel root=Theme.backgroundPanel();root.setLayout(new GridBagLayout());JPanel p=Theme.card();p.setLayout(new GridBagLayout());p.setPreferredSize(new Dimension(390,330));GridBagConstraints g=new GridBagConstraints();g.insets=new Insets(7,6,7,6);g.fill=GridBagConstraints.HORIZONTAL;g.gridx=0;g.gridy=0;g.gridwidth=2;JLabel title=new JLabel("BITS Inventory",SwingConstants.CENTER);title.setFont(title.getFont().deriveFont(Font.BOLD,22f));p.add(title,g);g.gridwidth=1;g.gridy++;p.add(new JLabel("Email"),g);g.gridx=1;p.add(email,g);g.gridx=0;g.gridy++;p.add(new JLabel("Password"),g);g.gridx=1;p.add(password,g);JButton login=new JButton("Sign in"),reg=new JButton("Create account");g.gridx=0;g.gridy++;p.add(login,g);g.gridx=1;p.add(reg,g);root.add(p);setContentPane(root);Theme.styleWindow(this);title.setForeground(Theme.TEAL);title.setFont(title.getFont().deriveFont(Font.BOLD,28f));login.setBackground(Theme.ACCENT);login.setForeground(Color.WHITE);reg.setBackground(Theme.SURFACE_2);login.addActionListener(e->login());password.addActionListener(e->login());reg.addActionListener(e->{new RegisterFrame(this).setVisible(true);});}
 private void login(){try{User u=new UserDAO().login(email.getText(),new String(password.getPassword()));if(u==null){JOptionPane.showMessageDialog(this,"Invalid email or password.");return;}dispose();new DashboardFrame(u).setVisible(true);}catch(SQLException ex){dbError(ex);}}
 static void dbError(Exception ex){JOptionPane.showMessageDialog(null,"Could not connect to MySQL. Check database/schema.sql and DB credentials.\n\nDetails: "+ex.getMessage(),"Database error",JOptionPane.ERROR_MESSAGE);}
}
